(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12;
  const w1y = Math.cos(y*0.016-t*0.22)*18 + Math.sin(x*0.014+t*0.3)*12;
  const w2x = Math.sin((x+w1x)*0.03+t*0.4)*6 + Math.cos((y+w1y)*0.025-t*0.35)*5;
  const w2y = Math.cos((y+w1y)*0.028-t*0.38)*6 + Math.sin((x+w1x)*0.022+t*0.45)*5;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*110,80+Math.cos(t*0.4)*55,0.075,2.1,0.9],
    [320+Math.cos(t*0.5)*110,160+Math.sin(t*0.7)*55,0.09,1.8,1.1],
    [240+Math.sin(t*0.3+2)*150,120+Math.cos(t*0.5+1)*95,0.055,2.4,0.8],
    [120+Math.cos(t*0.8+1)*85,180+Math.sin(t*0.6+3)*65,0.11,1.6,1.2],
    [360+Math.sin(t*0.4+4)*95,60+Math.cos(t*0.9+2)*75,0.065,2.7,0.7],
    [240+Math.cos(t*0.35+5)*130,200+Math.sin(t*0.55)*85,0.085,2.0,1.0],
    [80+Math.sin(t*0.7+3)*100,40+Math.cos(t*0.3+5)*80,0.07,2.2,0.85],
    [400+Math.cos(t*0.45+2)*90,190+Math.sin(t*0.65+4)*70,0.095,1.9,1.15],
    [200+Math.sin(t*0.55+1)*120,220+Math.cos(t*0.75+3)*60,0.06,2.5,0.75]
  ];
  let aS=0, iS=0, cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave=Math.sin(d*f-t*sp);
    aS+=wave*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.sin(d*f*0.4-t*sp*0.3+Math.atan2(sy-sY,sx-sX)*2)*w*0.5;
  }
  const aN=aS/6.8, iN=iS/6.8, cN=cS/6.8;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0))/2
    +Math.sin((sx+sy)*0.11+t*2.2)*0.25+Math.sin((sx-sy)*0.09-t*1.8)*0.25;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)+Math.sin(dist*0.038+ang*4.5-t*1.0))*0.35;
  const micro=(Math.sin(sx*0.12+t*1.5)*Math.sin(sy*0.13-t*1.2)+Math.sin((sx+sy)*0.08+t*0.9)*0.4)*0.2;
  const cross=Math.sin(aN*2.5+iN*1.8)*0.3+Math.sin(aN-iN)*0.2;
  const feed=Math.tanh((aN-iN*0.65+bg*0.25+spiral+micro+cross)*2.0);
  const inhibit=Math.tanh((-aN*0.8+iN*1.1+bg*0.15-spiral*0.5+cN)*1.8);
  const pattern=Math.tanh((feed-inhibit*0.6+cN*0.3)*1.6);
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.5)*1.4)*0.25;
  const blend=pattern*0.7+cell*0.3;
  const v=blend*0.5+0.5;
  const breathe=0.85+Math.sin(t*0.4)*0.1+Math.sin(t*0.7+1)*0.05;
  const edge=Math.abs(pattern)>0.65?1.2:Math.abs(pattern)>0.35?1.05:0.92;
  const lum=breathe*edge;
  const pal=[
    [5,12,52],[12,42,82],[18,85,108],[25,138,128],
    [85,168,135],[180,195,90],[225,175,60],[215,125,65],
    [185,72,72],[130,38,72],[72,18,58],[30,12,48],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const sh=Math.sin(pattern*3.5)*8;
  return[
    Math.min(255,Math.max(0,((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum+sh))|0),
    Math.min(255,Math.max(0,((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum+sh*0.5))|0),
    Math.min(255,Math.max(0,((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum-sh*0.3))|0)
  ];
}
